/// A stream object using `/Filter /ASCIIHexDecode` is decoded and its plaintext
/// content is emitted so signatures can match it.
#[test]
fn ascii_hex_stream_decoded() {
    // Hex of "MALWARETEST" followed by the '>' terminator.
    let hex = "4D414C5741524554455354>";
    let pdf = format!(
        "%PDF-1.7\n\
         1 0 obj\n\
         << /Length 23 /Filter /ASCIIHexDecode >>\n\
         stream\n\
         {hex}\n\
         endstream\n\
         endobj\n\
         trailer\n<< /Size 2 /Root 1 0 R >>\n%%EOF\n"
    );
    let mut budget = Budget::new(Limits::default());
    let entries = extract(Format::Pdf, &pdf.as_bytes(), &mut budget).unwrap();
    assert!(
        entries
            .iter()
            .any(|e| e.data.windows(11).any(|w| w == b"MALWARETEST")),
        "decoded ASCIIHexDecode stream should contain MALWARETEST, got {entries:?}"
    );
}

